<?php /* Template Name: Discover People */ get_header(); $search = isset( $_GET['member_search'] ) ? sanitize_text_field( wp_unslash( $_GET['member_search'] ) ) : ''; $interest = isset( $_GET['interest'] ) ? sanitize_text_field( wp_unslash( $_GET['interest'] ) ) : ''; $sort = sd_social_current_sort(); $members = sd_social_members_query( $search, $interest, $sort, isset( $_GET['paged'] ) ? absint( $_GET['paged'] ) : 1, 12 ); ?><main id="primary" class="sd-main sd-discovery-main"><div class="sd-container sd-content-wrap"><header class="sd-page-header"><div class="sd-breadcrumbs"><?php esc_html_e( 'Discover', 'social-discovery' ); ?></div><h1><?php esc_html_e( 'Find your people', 'social-discovery' ); ?></h1><p><?php esc_html_e( 'Search public member profiles by name and explore shared interests.', 'social-discovery' ); ?></p></header><?php get_template_part( 'template-parts/discovery/search-toolbar' ); ?><?php get_template_part( 'template-parts/discovery/interest-filters' ); ?><?php if ( ! empty( $members['users'] ) ) : ?><?php if ( 'list' === sd_get_option( 'sd_social_member_layout' ) ) { get_template_part( 'template-parts/discovery/member-list', null, array( 'members' => $members['users'] ) ); } else { get_template_part( 'template-parts/discovery/member-grid', null, array( 'members' => $members['users'] ) ); } ?><?php else : ?><div class="sd-card sd-empty"><h2><?php esc_html_e( 'No public members found', 'social-discovery' ); ?></h2><p><?php esc_html_e( 'Try a different search or interest filter.', 'social-discovery' ); ?></p></div><?php endif; ?><?php if ( is_user_logged_in() ) { get_template_part( 'template-parts/discovery/recommendations' ); } ?></div></main><?php get_footer(); ?>
